function normalizeGraph(raw,strict=true){if(!raw||!Array.isArray(raw.nodes)||!Array.isArray(raw.edges)||raw.nodes.length>250||raw.edges.length>600)throw Error(t('invalidImport'));const ids=new Set;const nodes=raw.nodes.map(n=>{if(!n||typeof n.id!=='string'||n.id.length>100||ids.has(n.id)||!componentMap.has(n.type))throw Error(t('invalidImport'));ids.add(n.id);const c=componentMap.get(n.type);return{id:n.id,type:n.type,label:String(n.label||c.label||n.type).slice(0,100),x:finite(n.x,100,-50000,50000),y:finite(n.y,100,-50000,50000),replicas:Math.round(finite(n.replicas,1,1,1000)),capacity:finite(n.capacity,c.maxQPS||1000,1),latency:finite(n.latency,c.latencyMs??1,0,1000000),config:n.config&&typeof n.config==='object'?JSON.parse(JSON.stringify(n.config)):{}};});const edgeIds=new Set;const edges=raw.edges.map((edge,i)=>{if(!edge||!ids.has(edge.source)||!ids.has(edge.target)||edge.source===edge.target)throw Error(t('invalidImport'));const id=String(edge.id||'edge-'+i).slice(0,100);if(edgeIds.has(id))throw Error(t('invalidImport'));edgeIds.add(id);return{id,source:edge.source,target:edge.target,protocol:String(edge.protocol||'HTTP').slice(0,40)};});const annotations=(Array.isArray(raw.annotations)?raw.annotations:[]).slice(0,200).map(a=>a&&a.kind==='text'?{id:String(a.id||uid('note')).slice(0,100),kind:'text',text:String(a.text||'').slice(0,1000),x:finite(a.x,0,-50000,50000),y:finite(a.y,0,-50000,50000)}:{id:String(a&&a.id||uid('stroke')).slice(0,100),kind:'stroke',points:(a&&Array.isArray(a.points)?a.points:[]).slice(0,3000).map(p=>[finite(p[0],0,-50000,50000),finite(p[1],0,-50000,50000)])});const g={nodes,edges,annotations};if(strict&&E.validateGraph){const v=E.validateGraph(g);if(v&&v.valid===false)throw Error((v.errors||[]).join(' · ')||t('invalidImport'));}return g;}
function starter(p){const raw=p.starter||{nodes:[],edges:[]};try{return normalizeGraph(raw,false);}catch(_){return{nodes:[],edges:[],annotations:[]};}}
try{graph=db.current&&!queryProblem?normalizeGraph(db.current.graph,false):starter(problem());decisions=db.current&&!queryProblem&&Array.isArray(db.current.decisions)?db.current.decisions.slice(0,200):[];notes=db.current&&!queryProblem?String(db.current.notes||'').slice(0,10000):'';}catch(_){graph=starter(problem());}
function persist(){db.current={problemId,graph:clone(graph),decisions:clone(decisions),notes};try{localStorage.setItem(KEY,JSON.stringify(db));storageOkay=true;}catch(_){storageOkay=false;}$('save-status').textContent=t(storageOkay?'saved':'unsaved');}
function toast(msg){$('studio-status').textContent=msg;$('studio-status').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('studio-status').classList.remove('visible'),4200);}
